export const phy1Tasks={"stores": [{"id": "compare", "title": "Explain the quantities and mechanism", "kind": "stores", "type": "compare", "cases": [["0", "Which describes a system?", ["An object or group of objects", "Only a numerical answer", "Only an energy-transfer pathway"], 0, "Identify which objects belong inside the boundary."], ["1", "Which is a transfer pathway rather than a store?", ["Chemical", "Heating", "Kinetic"], 1, "Heating describes a process of transfer."], ["2", "A ball rises with negligible air resistance. Its kinetic energy mainly transfers into…", ["New energy created by height", "An electrical store in empty space", "The gravitational store of the ball–Earth system"], 2, "Include Earth in the gravitational system."]]}, {"id": "calculate", "title": "Calculate with the correct units", "kind": "stores-data", "type": "numeric", "prompt": "Fresh input 500 J; useful store 350 J. Calculate energy accounted in other stores.", "answer": 150, "unit": "J", "reasonChoices": ["500−350; total energy is accounted", "500+350; add all stated numbers", "350−500; useful energy minus input"], "reason": 0, "why": "Substitute the supplied quantities using SI units and the stated boundary."}, {"id": "model", "title": "Predict and compare the controlled model", "kind": "stores-model", "type": "experiment", "experiment": "stores", "why": "Record every required setting with a correct numerical prediction and a bounded interpretation."}], "kinetic": [{"id": "compare", "title": "Explain the quantities and mechanism", "kind": "kinetic", "type": "compare", "cases": [["0", "Kinetic energy is calculated as…", ["½mv²", "mv", "½m²v"], 0, "Square the speed before multiplying by half the mass."], ["1", "For2 kg at 3 m/s, kinetic energy is…", ["18 J", "9 J", "6 J"], 1, "0.5×2×9=9."], ["2", "Doubling speed at fixed mass changes kinetic energy by…", ["A factor of 2", "No change", "A factor of 4"], 2, "The squared speed dependence matters."]]}, {"id": "calculate", "title": "Calculate with the correct units", "kind": "kinetic-data", "type": "numeric", "prompt": "Fresh moving object: 4 kg at 5 m/s. Calculate kinetic energy.", "answer": 50, "unit": "J", "reasonChoices": ["½×4×5²", "4×5; multiply mass by speed", "½×4×5; use speed without squaring"], "reason": 0, "why": "Substitute the supplied quantities using SI units and the stated boundary."}, {"id": "model", "title": "Predict and compare the controlled model", "kind": "kinetic-model", "type": "experiment", "experiment": "kinetic", "why": "Record every required setting with a correct numerical prediction and a bounded interpretation."}], "gravitational": [{"id": "compare", "title": "Explain the quantities and mechanism", "kind": "gravitational", "type": "compare", "cases": [["0", "The equation for gravitational energy change is…", ["mgh", "½mv²", "m/g/h"], 0, "Use mass, supplied field strength and vertical height change."], ["1", "2 kg raised 3 m with g = 10 N/kg gains…", ["600 J", "60 J", "15 J"], 1, "2×10×3=60."], ["2", "The height in this calculation is…", ["Every metre of an inclined path", "The width of the object", "Vertical change from the reference level"], 2, "Separate vertical displacement from route length."]]}, {"id": "calculate", "title": "Calculate with the correct units", "kind": "gravitational-data", "type": "numeric", "prompt": "Fresh lift: 3 kg through 4 m; supplied g = 10 N/kg. Calculate energy gained.", "answer": 120, "unit": "J", "reasonChoices": ["3×10×4", "3×10÷4; divide by vertical rise", "3×4; omit field strength"], "reason": 0, "why": "Substitute the supplied quantities using SI units and the stated boundary."}, {"id": "model", "title": "Predict and compare the controlled model", "kind": "gravitational-model", "type": "experiment", "experiment": "gravitational", "why": "Record every required setting with a correct numerical prediction and a bounded interpretation."}], "elastic": [{"id": "compare", "title": "Explain the quantities and mechanism", "kind": "elastic", "type": "compare", "cases": [["0", "Elastic potential energy is calculated with…", ["½ke²", "ke", "½k²e"], 0, "Square extension, not spring constant."], ["1", "k = 100 N/m and e = 0.10 m store…", ["10 J", "0.5 J", "5 J"], 1, "0.5×100×0.01=0.5."], ["2", "Doubling extension at fixed k changes stored energy by…", ["A factor of 2", "No change", "A factor of 4"], 2, "Extension is squared."]]}, {"id": "calculate", "title": "Calculate with the correct units", "kind": "elastic-data", "type": "numeric", "prompt": "Fresh spring: k = 200 N/m, extension 10 cm. Calculate stored energy within proportional range.", "answer": 1, "unit": "J", "reasonChoices": ["½×200×0.10²", "½×200×10²; substitute centimetres", "200×0.10; omit the square and half"], "reason": 0, "why": "Substitute the supplied quantities using SI units and the stated boundary."}, {"id": "model", "title": "Predict and compare the controlled model", "kind": "elastic-model", "type": "experiment", "experiment": "elastic", "why": "Record every required setting with a correct numerical prediction and a bounded interpretation."}], "heating": [{"id": "compare", "title": "Explain the quantities and mechanism", "kind": "heating", "type": "compare", "cases": [["0", "Specific heat capacity is energy per…", ["1 kg per 1°C rise", "Any mass per final temperature reading", "One metre per second"], 0, "Use the defined mass and temperature change."], ["1", "The thermal energy equation is…", ["ΔE=½mv²", "ΔE=mcΔθ", "ΔE=m/c/Δθ"], 1, "Keep the quantities and units distinct."], ["2", "A block warms 20→32°C. Temperature change is…", ["32°C", "52°C", "12°C"], 2, "Subtract initial from final temperature."]]}, {"id": "calculate", "title": "Calculate with the correct units", "kind": "heating-data", "type": "numeric", "prompt": "Fresh block gains 12000 J; mass 0.5 kg; temperature rise 24°C. Calculate c.", "answer": 1000, "unit": "J/(kg°C)", "reasonChoices": ["12000÷(0.5×24)", "12000÷0.5÷final temperature", "12000×0.5×24; multiply all values"], "reason": 0, "why": "Substitute the supplied quantities using SI units and the stated boundary."}, {"id": "model", "title": "Predict and compare the controlled model", "kind": "heating-model", "type": "experiment", "experiment": "heating", "why": "Record every required setting with a correct numerical prediction and a bounded interpretation."}]};
export const tasksForPhy1=k=>phy1Tasks[k];export const validPhy1=(c,a)=>a!==''&&a!==null&&a!==undefined&&Number(a)===c[3];export const numericPhy1=(v,a)=>v!==''&&v!==null&&v!==undefined&&Number.isFinite(Number(v))&&Math.abs(Number(v)-a)<.001;export const advancePhy1=(r,n,v)=>Number.isInteger(n)&&n>=0&&n<r.length&&r[n]===v?n+1:n;
export const storeCases={launch:{label:'Upward launch',values:[100,300,0],names:['Kinetic','Gravitational','Surroundings'],value:300,target:'gravitational'},collision:{label:'Collision',values:[0,0,400],names:['Kinetic','Gravitational','Thermal/deformation'],value:400,target:'other stores'},accelerate:{label:'Constant-force acceleration',values:[300,0,100],names:['Kinetic','Remaining source','Thermal'],value:300,target:'kinetic'},brake:{label:'Vehicle slowing',values:[0,0,400],names:['Kinetic','Unused source','Thermal'],value:400,target:'thermal'},kettle:{label:'Electric kettle',values:[320,80,0],names:['Water thermal','Surroundings','Other'],value:320,target:'water thermal'}};
export function kinetic(m,v){if(!Number.isFinite(m)||m<=0||!Number.isFinite(v)||v<0)throw new RangeError('Positive mass and non-negative speed required.');return .5*m*v*v;}
export function gravitational(m,g,h){if(!Number.isFinite(m)||m<=0||!Number.isFinite(g)||g<=0||!Number.isFinite(h)||h<0)throw new RangeError('Use positive mass/g and non-negative height change.');return m*g*h;}
export function elastic(k,e){if(!Number.isFinite(k)||k<=0||!Number.isFinite(e)||e<0||e>.2)throw new RangeError('This proportional model supports extension0–0.20m only.');return .5*k*e*e;}
export function heating(m,loss){if(![.5,1].includes(m)||![0,.1].includes(loss))throw new RangeError('Use the stated model block settings.');let input=6000,block=input*(1-loss),delta=block/(m*1000);return{input,block,elsewhere:input-block,delta,final:20+delta,apparent:input/(m*delta),actual:1000};}
export const experimentOptions={stores:{a:Object.entries(storeCases).map(([k,s])=>[k,s.label]),b:[['closed','Wider closed account']],labels:['Situation','Boundary'],unit:'J in named target store'},kinetic:{a:[['2','2 kg'],['4','4 kg']],b:[['3','3 m/s'],['6','6 m/s']],labels:['Mass','Speed'],unit:'J kinetic'},gravitational:{a:[['2','2 kg'],['4','4 kg']],b:[['3','3 m'],['6','6 m']],labels:['Mass','Vertical rise (g=10 N/kg)'],unit:'J gravitational'},elastic:{a:[['100','100 N/m'],['200','200 N/m']],b:[['0.1','0.10 m'],['0.2','0.20 m']],labels:['Spring constant','Extension within supported range'],unit:'J elastic'},heating:{a:[['0.5','0.5 kg'],['1','1 kg']],b:[['0','Ideal: no input loss'],['0.1','10% input to surroundings']],labels:['Block mass','Energy loss model'],unit:'°C temperature rise'}};
export function experimentResult(kind,a,b){let o=experimentOptions[kind];if(!o||!o.a.some(x=>x[0]===String(a))||!o.b.some(x=>x[0]===String(b)))throw new RangeError('Choose stated model settings.');if(kind==='stores')return{...storeCases[a],total:400};if(kind==='kinetic')return{m:Number(a),v:Number(b),value:kinetic(Number(a),Number(b))};if(kind==='gravitational')return{m:Number(a),g:10,h:Number(b),value:gravitational(Number(a),10,Number(b))};if(kind==='elastic')return{k:Number(a),e:Number(b),value:elastic(Number(a),Number(b))};let r=heating(Number(a),Number(b));return{m:Number(a),loss:Number(b),...r,value:r.delta};}
export const experimentCases=k=>experimentOptions[k].a.flatMap(([a])=>experimentOptions[k].b.map(([b])=>a+':'+b));export const experimentValid=(kind,v)=>experimentCases(kind).every(k=>v.observed?.includes(k))&&v.interpretation==='limited';
